}

func TestCompleteEnrollment_RejectsNonHTTPSWhenAllowInsecureUnset(t *testing.T) {
	t.Parallel()

	// Arrange: a tampered or stale state file where ServerURL was downgraded
	// to plaintext http for a non-loopback host. CompleteEnrollment must
	// refuse before sending the api_key on the wire.
	state := &State{
		ServerURL:              "http://fleet.example.com",
		AllowInsecureTransport: false,
		IdentityPrivateKeyHex:  hex.EncodeToString(make([]byte, ed25519.PrivateKeySize)),
		IdentityPublicKeyHex:   hex.EncodeToString(make([]byte, ed25519.PublicKeySize)),
	}

	// Act
	err := CompleteEnrollment(t.Context(), state, "fleet_some_key")

	// Assert
	require.Error(t, err)
	assert.Contains(t, err.Error(), "https")
	assert.Empty(t, state.APIKey, "rejected URL must not leave api_key written into state")
}

func TestCompleteEnrollment_PreservesStateOnHandshakeFailure(t *testing.T) {
	t.Parallel()

	// Arrange: valid URL, but the supplied api_key does not match what the
	// fake expects, so BeginAuthHandshake will return Unauthenticated.
	pub, priv, err := GenerateKeypair()
	require.NoError(t, err)
	fake := &fakeAgentGateway{
		expectedAPIKey: "right-key",
		identityPub:    pub,
		challenge:      bytes.Repeat([]byte{0x10}, 32),
	}
	srv := newFakeServer(t, fake)
	state := &State{
		ServerURL:              srv.URL,
		AllowInsecureTransport: true,
		IdentityPrivateKeyHex:  hex.EncodeToString(priv),
		IdentityPublicKeyHex:   hex.EncodeToString(pub),
	}

	// Act
	err = CompleteEnrollment(t.Context(), state, "wrong-key")

	// Assert
	require.Error(t, err)
	assert.ErrorIs(t, err, ErrBeginAuthRejected)
	// The rejected key must NOT be persisted into state; on retry, the
	// caller can supply a different api_key without first re-zeroing it.
	assert.Empty(t, state.APIKey)
	assert.Empty(t, state.SessionToken)
	assert.True(t, state.SessionExpiresAt.IsZero())
}

func TestCompleteEnrollment_RejectsEmptyInputs(t *testing.T) {
	t.Parallel()

	// Act
	errNilState := CompleteEnrollment(t.Context(), nil, "k")
	errEmptyKey := CompleteEnrollment(t.Context(), &State{}, "")

	// Assert
	require.Error(t, errNilState)
	require.Error(t, errEmptyKey)
	assert.Contains(t, errNilState.Error(), "state")
	assert.Contains(t, errEmptyKey.Error(), "apiKey")
}

func TestRegister_TimesOutAgainstBlackholeServer(t *testing.T) {
	// Arrange
	prev := handshakeStepTimeout
	handshakeStepTimeout = 250 * time.Millisecond
	t.Cleanup(func() { handshakeStepTimeout = prev })

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	require.NoError(t, err)

	// testing.T.Cleanup is not safe to call from a goroutine, so the accept
	// loop collects conns under a lock and a single Cleanup closes them all.
	var (
		mu    sync.Mutex
		conns []net.Conn
	)
	t.Cleanup(func() {
		_ = ln.Close()
		mu.Lock()
		defer mu.Unlock()
		for _, c := range conns {
			_ = c.Close()
		}
	})
	go func() {
		for {
			conn, err := ln.Accept()
			if err != nil {
				return
			}
			mu.Lock()
			conns = append(conns, conn)
			mu.Unlock()
		}
	}()

	// Act
	start := time.Now()
	_, err = Register(t.Context(), RegisterParams{
		ServerURL:              "http://" + ln.Addr().String(),
		Name:                   "stuck",
		Code:                   "anything",
		AllowInsecureTransport: true,
	})
	elapsed := time.Since(start)

	// Assert
	require.Error(t, err)
	assert.Less(t, elapsed, 5*time.Second, "Register should not block past the per-call timeout")
}

func TestValidateServerURL(t *testing.T) {
	t.Parallel()

	cases := []struct {
		name          string
		url           string
		allowInsecure bool
		wantErr       string
	}{
		{name: "https accepted", url: "https://fleet.example.com", allowInsecure: false, wantErr: ""},
		{name: "loopback http localhost", url: "http://localhost:4000", allowInsecure: false, wantErr: ""},
		{name: "loopback http 127.0.0.1", url: "http://127.0.0.1:4000", allowInsecure: false, wantErr: ""},
		{name: "loopback http 127.x.x.x", url: "http://127.5.6.7:4000", allowInsecure: false, wantErr: ""},
		{name: "loopback http ipv6", url: "http://[::1]:4000", allowInsecure: false, wantErr: ""},
		{name: "remote http rejected", url: "http://fleet.example.com", allowInsecure: false, wantErr: "https"},
		{name: "remote http allowed via flag", url: "http://fleet.example.com", allowInsecure: true, wantErr: ""},
		{name: "unknown scheme rejected", url: "ftp://fleet.example.com", allowInsecure: false, wantErr: "scheme"},
		{name: "missing host rejected", url: "https://", allowInsecure: false, wantErr: "host"},
		{name: "userinfo rejected", url: "https://fleet.example.com@attacker.example", allowInsecure: false, wantErr: "userinfo"},
		{name: "userinfo with password rejected", url: "https://user:pass@attacker.example", allowInsecure: false, wantErr: "userinfo"},
		{name: "query string rejected", url: "https://fleet.example.com?foo=bar", allowInsecure: false, wantErr: "query"},
		{name: "fragment rejected", url: "https://fleet.example.com#frag", allowInsecure: false, wantErr: "fragment"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			// Act
			err := ValidateServerURL(tc.url, tc.allowInsecure)

			// Assert
			if tc.wantErr == "" {
				require.NoError(t, err)
				return
			}
			require.Error(t, err)
			assert.Contains(t, err.Error(), tc.wantErr)
		})
	}
}

import { renderHook } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";

import { type BulkAction } from "../BulkActions/types";
import { ACTION_PERMISSIONS, usePermittedActions } from "./actionPermissions";
import { deviceActions, performanceActions, settingsActions, type SupportedAction } from "./constants";

vi.mock("@/protoFleet/store", () => ({
  usePermissions: vi.fn(),
}));

import { usePermissions } from "@/protoFleet/store";

const action = (a: SupportedAction): BulkAction<SupportedAction> => ({
  action: a,
  title: a,
  icon: null,
  actionHandler: () => {},
  requiresConfirmation: false,
});

describe("usePermittedActions", () => {
  it("filters out actions whose required catalog key is missing", () => {
    vi.mocked(usePermissions).mockReturnValue(["miner:reboot"]);

    const { result } = renderHook(() =>
      usePermittedActions([action(deviceActions.reboot), action(deviceActions.unpair)]),
    );

    expect(result.current.map((a) => a.action)).toEqual([deviceActions.reboot]);
  });

  it("keeps actions whose required key is granted", () => {
    vi.mocked(usePermissions).mockReturnValue(["miner:reboot", "miner:delete"]);

    const { result } = renderHook(() =>
      usePermittedActions([action(deviceActions.reboot), action(deviceActions.unpair)]),
    );

    expect(result.current.map((a) => a.action)).toEqual([deviceActions.reboot, deviceActions.unpair]);
  });

  it("requires every key when the mapping is an AND-list", () => {
    // miningPool needs both miner:update_pools and pool:read; holding
    // only one is insufficient because the pool-selection flow calls
    // ListPools before the miner-side write.
    vi.mocked(usePermissions).mockReturnValue(["miner:update_pools"]);
    const onlyMinerKey = renderHook(() => usePermittedActions([action(settingsActions.miningPool)]));
    expect(onlyMinerKey.result.current).toEqual([]);

    vi.mocked(usePermissions).mockReturnValue(["miner:update_pools", "pool:read"]);
    const both = renderHook(() => usePermittedActions([action(settingsActions.miningPool)]));
    expect(both.result.current.map((a) => a.action)).toEqual([settingsActions.miningPool]);

    // Firmware update needs miner:reboot too because successful installs
    // automatically reboot the miner after activation.
    vi.mocked(usePermissions).mockReturnValue(["miner:firmware_update"]);
    const firmwareWithoutReboot = renderHook(() => usePermittedActions([action(deviceActions.firmwareUpdate)]));
    expect(firmwareWithoutReboot.result.current).toEqual([]);

    vi.mocked(usePermissions).mockReturnValue(["miner:firmware_update", "miner:reboot"]);
    const firmwareWithReboot = renderHook(() => usePermittedActions([action(deviceActions.firmwareUpdate)]));
    expect(firmwareWithReboot.result.current.map((a) => a.action)).toEqual([deviceActions.firmwareUpdate]);
  });

  it("passes through actions without a mapped permission (e.g. viewMiner)", () => {
    vi.mocked(usePermissions).mockReturnValue([]);

    const viewMiner: BulkAction<"viewMiner"> = {
      action: "viewMiner",
      title: "View miner",
      icon: null,
      actionHandler: () => {},
      requiresConfirmation: false,
    };

    const { result } = renderHook(() => usePermittedActions([viewMiner]));

    expect(result.current.map((a) => a.action)).toEqual(["viewMiner"]);
  });

  it("hides every action when permissions are empty", () => {
    // Pre-U10a sessions and FIELD_TECH-without-miner-permissions both
    // hit this path; the menu collapses to nothing rather than showing
    // controls that 403.
    vi.mocked(usePermissions).mockReturnValue([]);

    const { result } = renderHook(() =>
      usePermittedActions([action(deviceActions.reboot), action(deviceActions.blinkLEDs)]),
    );

    expect(result.current).toEqual([]);
  });
});

describe("ACTION_PERMISSIONS", () => {
  it("anchors well-known actions to their server-side catalog keys", () => {
    // ACTION_PERMISSIONS is typed `Record<SupportedAction, ...>`, so
    // exhaustiveness is enforced at compile time — adding a new
    // SupportedAction without an entry fails tsc. This spot-check
    // anchors a few high-traffic mappings against rpc_permissions.go
    // so a wire-misalignment lands in code review instead of an
    // operator's lap.
    expect(ACTION_PERMISSIONS[deviceActions.reboot]).toBe("miner:reboot");
    expect(ACTION_PERMISSIONS[deviceActions.blinkLEDs]).toBe("miner:blink_led");
    // Unpair routes through FleetManagementService.DeleteMiners
    // (miner:delete) on the server, not MinerCommandService.Unpair.
    expect(ACTION_PERMISSIONS[deviceActions.unpair]).toBe("miner:delete");
    expect(ACTION_PERMISSIONS[deviceActions.firmwareUpdate]).toEqual(["miner:firmware_update", "miner:reboot"]);
    expect(ACTION_PERMISSIONS[deviceActions.downloadLogs]).toBe("miner:download_logs");
    expect(ACTION_PERMISSIONS[performanceActions.curtail]).toBe("curtailment:manage");
    expect(ACTION_PERMISSIONS[settingsActions.miningPool]).toEqual(["miner:update_pools", "pool:read"]);
  });
});

import { APIRequestContext, expect, Page } from "@playwright/test";

const FAKE_PROTO_RIG_SERIAL_PREFIX = "PROTO-SIM-";

type WaitForAuthenticatedApiRecoveryParams = {
  accessToken: string;
  path: string;
  request: APIRequestContext;
  timeoutMs: number;
};

type SafeSimulatorTargetParams = {
  actionDescription: string;
  request: APIRequestContext;
};

async function getAuthenticatedApiStatus({
  accessToken,
  path,
  request,
}: Omit<WaitForAuthenticatedApiRecoveryParams, "timeoutMs">) {
  try {
    const response = await request.get(path, {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    });

    return response.status();
  } catch {
    return 0;
  }
}

export async function getAuthAccessToken(page: Page) {
  return page.evaluate(() => {
    const authData = window.localStorage.getItem("proto-os-auth");
    if (!authData) {
      throw new Error("Missing proto-os-auth in localStorage");
    }

    const parsed = JSON.parse(authData) as {
      state?: {
        auth?: {
          authTokens?: {
            accessToken?: { value?: string };
          };
        };
      };
    };

    const accessToken = [REDACTED];
    if (!accessToken) {
      throw new Error("Missing access token in proto-os-auth");
    }

    return accessToken;
  });
}

export async function assertSafeSimulatorTarget({ actionDescription, request }: SafeSimulatorTargetParams) {
  const response = await request.get("/api/v1/system");
  expect(response.ok()).toBeTruthy();

  const data = (await response.json()) as {
    "system-info": {
      cb_sn?: string;
      product_name?: string;
      manufacturer?: string;
      model?: string;
    };
  };

  const systemInfo = data["system-info"];
  const serialNumber = systemInfo.cb_sn ?? "";

  if (!serialNumber.startsWith(FAKE_PROTO_RIG_SERIAL_PREFIX)) {
    throw new Error(
      `Refusing to ${actionDescription} non-simulator target "${serialNumber || "unknown"}" (${systemInfo.manufacturer ?? "unknown"} ${systemInfo.product_name ?? systemInfo.model ?? "unknown"}).`,
    );
  }
}

export async function waitForAuthenticatedApiRecovery({
  accessToken,
  path,
  request,
  timeoutMs,
}: WaitForAuthenticatedApiRecoveryParams) {
  await expect.poll(() => getAuthenticatedApiStatus({ accessToken, path, request }), { timeout: timeoutMs }).toBe(200);
}

export async function waitForAuthenticatedApiOutage({
  accessToken,
  path,
  request,
  timeoutMs,
}: WaitForAuthenticatedApiRecoveryParams) {
  await expect
    .poll(() => getAuthenticatedApiStatus({ accessToken, path, request }), { timeout: timeoutMs })
    .not.toBe(200);
}

