			return nil, context.Canceled
		}
		return output, err
	}

	// Act
	err := install(ctx, InstallOptions{NodeEnvPath: "node.env", EtcdRootPasswordFile: rootPassword}, deps)

	// Assert
	require.ErrorContains(t, err, context.Canceled.Error())
